package net.gsantner.markor.knowledge;

import java.io.InputStream;

/**
 * Fixed, generated bytes for isolated FD transport QA only. This is NOT ONNX,
 * and must never be passed to ORT, a user file, or the package trust gate.
 */
final class KnowledgeE5LargeFdFixture {
    static final long LENGTH_BYTES = 17L * 1024L * 1024L + 73L;
    static final String SHA256 =
            "7afbc581e3a9a6682131f62221f2c263786b4a510074d504f39f10e3682c7f94";

    private KnowledgeE5LargeFdFixture() { }

    static boolean isPinned(final long length, final String sha256) {
        return length == LENGTH_BYTES && SHA256.equals(sha256);
    }

    /** Reproducible byte pattern; each caller gets a new constant-memory stream. */
    static InputStream open() {
        return new InputStream() {
            private long position;

            @Override public int read() {
                if (position >= LENGTH_BYTES) return -1;
                return valueAt(position++) & 0xff;
            }

            @Override public int read(final byte[] destination, final int offset, final int count) {
                if (destination == null) throw new NullPointerException("destination");
                if (offset < 0 || count < 0 || offset > destination.length - count) {
                    throw new IndexOutOfBoundsException("invalid fixture read bounds");
                }
                if (count == 0) return 0;
                if (position >= LENGTH_BYTES) return -1;
                final int copied = (int) Math.min((long) count, LENGTH_BYTES - position);
                for (int i = 0; i < copied; i++) {
                    destination[offset + i] = valueAt(position + i);
                }
                position += copied;
                return copied;
            }
        };
    }

    private static byte valueAt(final long offset) {
        return (byte) (offset * 31L + 17L);
    }
}
